css:
.bk-otomo2 h2{font-size:1.27em; color:#fff; background:#7a3b12; padding:1.5mm 3mm; margin:0 0 3mm; border-radius:3px;}
.bk-otomo2 h3{font-size:1.09em; color:#7a3b12; border-left:4px solid #7a3b12; padding-left:2.5mm; margin:5mm 0 2mm;}
.bk-otomo2 p{margin:0 0 3mm;}
.bk-otomo2 .old{background:#f3f3f3; border:1px solid #ccc; border-radius:3px; padding:2.5mm 3mm; margin:3mm 0; font-size:0.955em;}
.bk-otomo2 .old b{color:#666;}
.bk-otomo2 .now{background:#fff6dd; border:1px solid #e8cf86; border-radius:3px; padding:2.5mm 3mm; margin:3mm 0; font-size:0.955em;}
.bk-otomo2 .now b{color:#a35a00;}
.bk-otomo2 .memo{background:#eef5ec; border:1px solid #b9d4b1; border-radius:3px; padding:2.5mm 3mm; margin:3mm 0; font-size:0.955em;}
.bk-otomo2 .memo b{color:#3a6b2c;}
.bk-otomo2 table{border-collapse:collapse; width:100%; font-size:0.864em; margin:2mm 0 3mm;}
.bk-otomo2 th,.bk-otomo2 td{border:1px solid #e0c4ae; padding:1.2mm 1.5mm; vertical-align:top;}
.bk-otomo2 th{background:#f6e6da;}
.bk-otomo2 td.n{white-space:nowrap;}
.bk-otomo2 .small{font-size:0.818em; color:#666;}
.bk-otomo2 .time{float:right; font-size:0.773em; color:#f3dccb; font-weight:normal;}
.bk-otomo2 .q{font-weight:bold; color:#7a3b12; margin-top:3mm;}
.bk-otomo2 .a{color:#444; font-size:0.909em;}
